"""TaskWeaver plugin: dominusnode_report_session (generated by dominusnode_taskweaver.generate_plugins)."""

from taskweaver.plugin import Plugin, register_plugin

from dominusnode_taskweaver.runtime import run


@register_plugin
class DominusNodeReportSession(Plugin):
    def __call__(self, session_id, reason) -> str:
        return run(self, "report_session", {"session_id": session_id, "reason": reason})
